import{c as i,Z as e,Q as n,j as s,m as l,o as t}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"江雪","description":"","frontmatter":{"title":"江雪","author":"柳宗元","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/5.md","filePath":"books/shici/tangshi/5.md"}'),h={name:"books/shici/tangshi/5.md"};function c(d,a,u,_,m,p){const o=e("PoemAuthor"),r=e("PoemNav");return n(),s("div",null,[a[0]||(a[0]=l('<h1 id="江雪" tabindex="-1">江雪 <a class="header-anchor" href="#江雪" aria-label="Permalink to &quot;江雪&quot;">​</a></h1><p><strong>[唐] <a href="/authors/liuzongyuan.html">柳宗元</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>千山鸟飞绝，万径人踪灭。 孤舟蓑笠翁，独钓寒江雪。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>绝：无，没有</li><li>万径：虚指，指千万条路</li><li>人踪：人的脚印</li><li>蓑笠：蓑衣和斗笠</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>所有的山上，飞鸟的身影已经绝迹；所有的道路上，不见人影踪迹。江面孤舟上，一位披戴着蓑笠的老翁，独自在大雪覆盖的寒冷江面上垂钓。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗作于柳宗元被贬永州期间，是一首山水诗，描述了一幅江乡雪景图。山山是雪，路路皆白，飞鸟绝迹，人踪湮没，遐景苍茫，迩景孤冷。意境幽僻，情调凄寂，反映了诗人被贬后孤独抑郁的心情和不愿与当权者同流合污的高洁品格。全诗结构严谨，用词精确，是唐诗中的精品。</p>',10)),t(o,{name:"柳宗元",years:"773年－819年",desc:"字子厚，唐代文学家、哲学家、散文家和思想家，唐宋八大家之一。其诗风格清峭，多写山水田园。",link:"/authors/liuzongyuan"}),t(r)])}const P=i(h,[["render",c]]);export{b as __pageData,P as default};
